test("exactly 30 calendar days is accepted and both fields are returned", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-01" }), { accepted: true, daysUntilExpiry: 30 });
});
test("one day below the threshold is rejected", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-06-30" }), { accepted: false, daysUntilExpiry: 29 });
});
test("one day above the threshold is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-02" }), { accepted: true, daysUntilExpiry: 31 });
});
test("one calendar day until expiry is rejected", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-06-02" }), { accepted: false, daysUntilExpiry: 1 });
});
test("January 31 across leap day to March 1 counts 30 days and is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2024-01-31", expiryDate: "2024-03-01" }), { accepted: true, daysUntilExpiry: 30 });
});
test("last day of a 31 day month with exactly 30 days left is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-03-31", expiryDate: "2026-04-30" }), { accepted: true, daysUntilExpiry: 30 });
});
test("last day of a month one below the threshold is rejected", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-03-31", expiryDate: "2026-04-29" }), { accepted: false, daysUntilExpiry: 29 });
});
test("December 1 to January 1 counts 31 days and is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-12-01", expiryDate: "2027-01-01" }), { accepted: true, daysUntilExpiry: 31 });
});
test("December to January exactly 30 days is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-12-02", expiryDate: "2027-01-01" }), { accepted: true, daysUntilExpiry: 30 });
});
test("December to January one below the threshold is rejected", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-12-03", expiryDate: "2027-01-01" }), { accepted: false, daysUntilExpiry: 29 });
});
test("a 31 day January from January 2 to February 1 counts 30 days and is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-01-02", expiryDate: "2026-02-01" }), { accepted: true, daysUntilExpiry: 30 });
});
test("first of a non-leap February to March 2 counts 29 days and is rejected", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-02-01", expiryDate: "2026-03-02" }), { accepted: false, daysUntilExpiry: 29 });
});
test("leap year February 28 to March 29 counts 30 days and is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2024-02-28", expiryDate: "2024-03-29" }), { accepted: true, daysUntilExpiry: 30 });
});
test("check on leap day with exactly 30 days left is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2024-02-29", expiryDate: "2024-03-30" }), { accepted: true, daysUntilExpiry: 30 });
});
test("check on leap day one below the threshold is rejected", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2024-02-29", expiryDate: "2024-03-29" }), { accepted: false, daysUntilExpiry: 29 });
});
test("last day of a non-leap February to March 29 counts 29 days and is rejected", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2025-02-28", expiryDate: "2025-03-29" }), { accepted: false, daysUntilExpiry: 29 });
});
